Write {"file_path":"D:\code\ESI.ts\src\core\util\retry.ts","content":"export interface RetryConfig {
  maxRetries?: number;
  baseDelayMs?: number;
  maxDelayMs?: number;
  retryMutations?: boolean;
}

export function retryDelay(
  attempt: number,
  baseMs: number,
  maxMs: number,
): number {
  const exponential = baseMs * Math.pow(2, attempt);
  const jitter = exponential * (0.75 + Math.random() * 0.5);
  return Math.min(jitter, maxMs);
}
"}

