      );
    });

    it('should not append datasource when undefined', () => {
      const def: EndpointDefinition = {
        path: 'status/',
        method: 'GET',
        requiresAuth: false,
      };
      const { path } = buildEndpointPath(def, []);
      expect(path).toBe('status/');
    });
  });

  describe('body extraction', () => {
    it('should extract body when hasBody is true', () => {
